def extract(path):
    return pd.read_csv(
        path,
        parse_dates=["tpep_pickup_datetime"],
        dtype={"VendorID": "str"},
    )

def load(df, path):
    df.to_parquet(path, index=False)

def run_etl(source, destination):
    try:
        load(transform(extract(source)), destination)
    except FileNotFoundError:
        print(f"Source file not found: {source}")
